#!/usr/bin/env node
// Turkish course: tests for assets/js/turkish-morph.js, the morphology engine (turkish/PROJECT.md section 3).
// Every expected form below was typed by hand from the written standard (TDK spelling), never generated by
// the engine, so a failure means the engine or this list is wrong. No dependencies; Node 18 or later.
//
//   node scripts/turkish/morph-test.mjs            run everything; exit 1 on a failure
//   node scripts/turkish/morph-test.mjs --verbose  also list the forms that pass
import path from "path";
import { createRequire } from "module";
import { fileURLToPath } from "url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const M = createRequire(import.meta.url)(path.join(ROOT, "assets/js/turkish-morph.js"));
const VERBOSE = process.argv.includes("--verbose");
let forms = 0, other = 0;
const failures = [];

// check one form: kind "form" counts toward the known-correct forms, "check" is any other assertion
function check(label, fn, want, kind = "form") {
  let got;
  try { got = fn(); } catch (e) { got = `threw ${e.message}`; }
  const ok = Array.isArray(want) ? JSON.stringify(got) === JSON.stringify(want) : got === want;
  if (kind === "form") forms++; else other++;
  if (!ok) failures.push(`${label}: expected ${JSON.stringify(want)}, got ${JSON.stringify(got)}`);
  else if (VERBOSE) console.log(`ok  ${label}: ${Array.isArray(want) ? want.join(", ") : want}`);
}
// a paradigm: six forms separated by |, ben … onlar; "-" skips a person; with has, the form only has to be a variant
function para(slug, base, list, has = false) {
  list.split("|").forEach((want, i) => {
    if (want === "-") return;
    check(`${slug} ${base} ${M.PERSONS[i]}`, () => {
      const r = M.form(slug, base, i);
      if (!r) return null;
      return has ? (r.variants.includes(want) ? want : r.variants.join(" / ")) : r.text;
    }, want);
  });
}
const dec = (base, o) => M.decline(base, o).text;
const build = (base, ids) => M.build(base, ids).text;
const conj = (base, spec) => { const r = M.conjugate(base, spec); return r && r.text; };

// ─────────────────────────── 1. harmony and assimilation ───────────────────────────
for (const [v, a, i] of [["a", "a", "ı"], ["ı", "a", "ı"], ["o", "a", "u"], ["u", "a", "u"], ["e", "e", "i"], ["i", "e", "i"], ["ö", "e", "ü"], ["ü", "e", "ü"]]) {
  check(`harmony after ${v}`, () => M.harmony2(v) + M.harmony4(v), a + i, "check");
}
check("voiceless consonants", () => [..."fstkçşhp"].every(M.voiceless) && ![..."bcdgğjlmnrvyz"].some(M.voiceless), true, "check");
for (const [w, want] of [["ev", "evler"], ["okul", "okullar"], ["kalem", "kalemler"], ["bilgisayar", "bilgisayarlar"], ["otobüs", "otobüsler"],
  ["harf", "harfler"], ["saat", "saatler"], ["rol", "roller"], ["kitap", "kitaplar"], ["göz", "gözler"]]) check(`plural ${w}`, () => M.text(M.plural(M.noun(w))), want);
for (const [w, loc, abl] of [["ev", "evde", "evden"], ["okul", "okulda", "okuldan"], ["park", "parkta", "parktan"], ["kitap", "kitapta", "kitaptan"],
  ["sokak", "sokakta", "sokaktan"], ["ofis", "ofiste", "ofisten"], ["ağaç", "ağaçta", "ağaçtan"], ["banka", "bankada", "bankadan"],
  ["köy", "köyde", "köyden"], ["Paris", "Paris'te", "Paris'ten"], ["Ankara", "Ankara'da", "Ankara'dan"], ["İstanbul", "İstanbul'da", "İstanbul'dan"],
  ["saat", "saatte", "saatten"], ["beş", "beşte", "beşten"]]) {
  check(`locative ${w}`, () => dec(w, { case: "loc" }), loc);
  check(`ablative ${w}`, () => dec(w, { case: "abl" }), abl);
}

// ─────────────────────────── 2. nouns: softening, vowel loss, buffers, loanwords ───────────────────────────
for (const [w, acc, dat, gen] of [
  ["kitap", "kitabı", "kitaba", "kitabın"], ["ağaç", "ağacı", "ağaca", "ağacın"], ["sokak", "sokağı", "sokağa", "sokağın"],
  ["çocuk", "çocuğu", "çocuğa", "çocuğun"], ["renk", "rengi", "renge", "rengin"], ["park", "parkı", "parka", "parkın"],
  ["top", "topu", "topa", "topun"], ["saç", "saçı", "saça", "saçın"], ["uç", "ucu", "uca", "ucun"], ["dört", "dördü", "dörde", "dördün"],
  ["kurt", "kurdu", "kurda", "kurdun"], ["umut", "umudu", "umuda", "umudun"], ["bilet", "bileti", "bilete", "biletin"],
  ["saat", "saati", "saate", "saatin"], ["kalp", "kalbi", "kalbe", "kalbin"], ["rol", "rolü", "role", "rolün"], ["harf", "harfi", "harfe", "harfin"],
  ["dikkat", "dikkati", "dikkate", "dikkatin"], ["kontrol", "kontrolü", "kontrole", "kontrolün"], ["ağız", "ağzı", "ağza", "ağzın"],
  ["burun", "burnu", "burna", "burnun"], ["oğul", "oğlu", "oğla", "oğlun"], ["isim", "ismi", "isme", "ismin"], ["şehir", "şehri", "şehre", "şehrin"],
  ["hak", "hakkı", "hakka", "hakkın"], ["sır", "sırrı", "sırra", "sırrın"], ["his", "hissi", "hisse", "hissin"], ["kayıt", "kaydı", "kayda", "kaydın"],
  ["su", "suyu", "suya", "suyun"], ["araba", "arabayı", "arabaya", "arabanın"], ["kapı", "kapıyı", "kapıya", "kapının"],
  ["Ankara", "Ankara'yı", "Ankara'ya", "Ankara'nın"], ["İstanbul", "İstanbul'u", "İstanbul'a", "İstanbul'un"], ["Mehmet", "Mehmet'i", "Mehmet'e", "Mehmet'in"],
  ["Türkiye", "Türkiye'yi", "Türkiye'ye", "Türkiye'nin"], ["ahlak", "ahlakı", "ahlaka", "ahlakın"]]) {
  check(`accusative ${w}`, () => dec(w, { case: "acc" }), acc);
  check(`dative ${w}`, () => dec(w, { case: "dat" }), dat);
  check(`genitive ${w}`, () => dec(w, { case: "gen" }), gen);
}
for (const [w, want] of [["kitap", "kitapla"], ["uçak", "uçakla"], ["şeker", "şekerle"], ["araba", "arabayla"], ["su", "suyla"], ["Ayşe", "Ayşe'yle"]])
  check(`instrumental ${w}`, () => dec(w, { case: "ins" }), want);
check("suda, sular, susuz", () => [dec("su", { case: "loc" }), dec("su", { pl: true }), build("su", ["SIZ"])], ["suda", "sular", "susuz"]);
check("ağızda (no vowel loss before a consonant)", () => dec("ağız", { case: "loc" }), "ağızda");
para("possessive", "ev", "evim|evin|evi|evimiz|eviniz|evleri");
para("possessive", "kitap", "kitabım|kitabın|kitabı|kitabımız|kitabınız|kitapları");
para("possessive", "araba", "arabam|araban|arabası|arabamız|arabanız|arabaları");
para("possessive", "çocuk", "çocuğum|çocuğun|çocuğu|çocuğumuz|çocuğunuz|çocukları");
para("possessive", "burun", "burnum|burnun|burnu|burnumuz|burnunuz|burunları");
para("possessive", "su", "suyum|suyun|suyu|suyumuz|suyunuz|suları");
para("possessive", "saat", "saatim|saatin|saati|saatimiz|saatiniz|saatleri");
para("possessive-locative", "ev", "evimde|evinde|evinde|evimizde|evinizde|evlerinde");
para("possessive-var", "para", "param var|paran var|parası var|paramız var|paranız var|paraları var");
check("arabasına, arabasında, arabasını", () => ["dat", "loc", "acc"].map(c => dec("araba", { poss: "o", case: c })), ["arabasına", "arabasında", "arabasını"]);
check("kapısının, evlerinden", () => [dec("kapı", { poss: "o", case: "gen" }), dec("ev", { poss: "onlar", case: "abl" })], ["kapısının", "evlerinden"]);
check("havalimanına, havalimanında", () => [dec("havalimanı", { case: "dat" }), dec("havalimanı", { case: "loc" })], ["havalimanına", "havalimanında"]);
para("compound-possessive", "okul çantası", "okul çantam|okul çantan|okul çantası|okul çantamız|okul çantanız|okul çantaları");
para("compound-possessive", "otobüs durağı", "otobüs durağım|-|otobüs durağı|-|-|otobüs durakları");

// ─────────────────────────── 3. pronouns, -ki, numbers, word building ───────────────────────────
para("pronoun-dative", "ben", "bana|sana|ona|bize|size|onlara");
para("pronoun-accusative", "ben", "beni|seni|onu|bizi|sizi|onları");
para("pronoun-locative", "ben", "bende|sende|onda|bizde|sizde|onlarda");
para("pronoun-ablative", "ben", "benden|senden|ondan|bizden|sizden|onlardan");
para("pronoun-genitive", "ben", "benim|senin|onun|bizim|sizin|onların");
para("pronoun-ile", "ben", "benimle|seninle|onunla|bizimle|sizinle|onlarla");
para("pronoun-genitive-ki", "ben", "benimki|seninki|onunki|bizimki|sizinki|onlarınki");
para("kendi-accusative", "kendi", "kendimi|kendini|kendisini|kendimizi|kendinizi|kendilerini");
for (const [w, c, want] of [["bu", "acc", "bunu"], ["bu", "dat", "buna"], ["bu", "loc", "bunda"], ["bu", "abl", "bundan"], ["bu", "gen", "bunun"],
  ["bu", "ins", "bununla"], ["şu", "dat", "şuna"], ["o", "ins", "onunla"]]) check(`${w} ${c}`, () => dec(w, { case: c }), want);
check("bunlar, şunlar, onlar", () => ["bu", "şu", "o"].map(w => dec(w, { pl: true })), ["bunlar", "şunlar", "onlar"]);
check("evdeki, evdekiler, evdekini", () => [build("ev", ["LOC", "KI"]), build("ev", ["LOC", "KI", "PL"]), build("ev", ["LOC", "KI", "ACC"])], ["evdeki", "evdekiler", "evdekini"]);
check("bugünkü, dünkü, yarınki", () => ["bugün", "dün", "yarın"].map(w => build(w, ["KI"])), ["bugünkü", "dünkü", "yarınki"]);
check("ordinals", () => ["bir", "iki", "üç", "dört", "beş", "altı", "dokuz", "on"].map(w => build(w, ["INCI"])),
  ["birinci", "ikinci", "üçüncü", "dördüncü", "beşinci", "altıncı", "dokuzuncu", "onuncu"]);
check("distributives", () => ["bir", "iki", "üç", "dört", "altı", "on"].map(w => build(w, ["SAR"])), ["birer", "ikişer", "üçer", "dörder", "altışar", "onar"]);
for (const [w, ids, want] of [["şeker", ["LI"], "şekerli"], ["İstanbul", ["LI"], "İstanbullu"], ["su", ["SIZ"], "susuz"], ["para", ["SIZ"], "parasız"],
  ["kitap", ["CI"], "kitapçı"], ["süt", ["CI"], "sütçü"], ["yol", ["CI"], "yolcu"], ["göz", ["LIK"], "gözlük"], ["kitap", ["LIK"], "kitaplık"],
  ["güzel", ["LIK"], "güzellik"], ["göz", ["LIK", "POSS1"], "gözlüğüm"], ["Türk", ["CA"], "Türkçe"], ["İngiliz", ["CA"], "İngilizce"],
  ["yavaş", ["CA"], "yavaşça"], ["sabah", ["LEYIN"], "sabahleyin"], ["yol", ["DAS"], "yoldaş"],
  ["meslek", ["DAS"], "meslektaş"], ["din", ["DAS"], "dindaş"], ["yurt", ["DAS"], "yurttaş"], ["gönül", ["DAS"], "gönüldaş"], ["sır", ["DAS"], "sırdaş"],
  ["bilim", ["SAL"], "bilimsel"], ["toplum", ["SAL"], "toplumsal"], ["kişi", ["SAL"], "kişisel"], ["tarih", ["SAL"], "tarihsel"], ["deney", ["SAL"], "deneysel"], ["küçük", ["DIM"], "küçücük"],
  ["ufak", ["DIM"], "ufacık"], ["sıcak", ["DIM"], "sıcacık"], ["az", ["DIM"], "azıcık"], ["dar", ["DIM"], "daracık"], ["anne", ["DIM", "POSS1"], "anneciğim"],
  ["adam", ["CAGIZ"], "adamcağız"], ["çocuk", ["CAGIZ"], "çocukcağız"], ["yeşil", ["IMSI"], "yeşilimsi"], ["sarı", ["IMSI"], "sarımsı"],
  ["ekşi", ["IMTIRAK"], "ekşimtırak"], ["temiz", ["LA", "PAST"], "temizledi"], ["güzel", ["LAS", "EVID"], "güzelleşmiş"],
  ["kir", ["LAN", "PAST"], "kirlendi"], ["az", ["AL", "PAST"], "azaldı"], ["iyi", ["LAS", "PAST"], "iyileşti"]]) {
  check(`${w} + ${ids.join(" + ")}`, () => build(w, ids), want);
}

// ─────────────────────────── 4. the copula on nominal predicates ───────────────────────────
para("copula-present", "öğrenci", "öğrenciyim|öğrencisin|öğrenci|öğrenciyiz|öğrencisiniz|öğrenciler");
para("copula-present", "doktor", "doktorum|doktorsun|doktor|doktoruz|doktorsunuz|doktorlar");
