para("copula-present", "meşgul", "meşgulüm|meşgulsün|-|-|-|-");
para("copula-present", "evde", "evdeyim|evdesin|evde|evdeyiz|evdesiniz|evdeler");
check("öğrencidir", () => M.form("copula-present", "öğrenci", "o").variants[1], "öğrencidir");
para("copula-present-negative", "öğrenci", "öğrenci değilim|öğrenci değilsin|öğrenci değil|öğrenci değiliz|öğrenci değilsiniz|öğrenci değiller");
para("copula-present-question", "öğrenci", "öğrenci miyim|öğrenci misin|öğrenci mi|öğrenci miyiz|öğrenci misiniz|öğrenciler mi");
para("copula-present-question", "yorgun", "yorgun muyum|yorgun musun|yorgun mu|-|-|-");
para("copula-present-negative-question", "hasta", "hasta değil miyim|-|hasta değil mi|-|-|-");
para("past-copula", "öğrenci", "öğrenciydim|öğrenciydin|öğrenciydi|öğrenciydik|öğrenciydiniz|öğrenciydiler");
para("past-copula", "doktor", "doktordum|-|doktordu|-|-|-");
para("past-copula", "Türk", "Türk'tüm|-|Türk'tü|-|-|-");
para("past-copula-negative", "öğrenci", "öğrenci değildim|öğrenci değildin|öğrenci değildi|öğrenci değildik|öğrenci değildiniz|öğrenci değildiler");
para("past-copula-question", "öğrenci", "öğrenci miydim|öğrenci miydin|öğrenci miydi|öğrenci miydik|öğrenci miydiniz|öğrenciler miydi");
para("past-copula", "evde", "-|-|-|-|-|evdelerdi", true);
para("reported-copula", "öğrenci", "öğrenciymişim|öğrenciymişsin|öğrenciymiş|öğrenciymişiz|öğrenciymişsiniz|öğrenciymişler");
