para("conditional-nominal", "doktor", "doktorsam|-|doktorsa|-|-|-");
para("conditional-nominal-negative", "öğrenci", "öğrenci değilsem|-|öğrenci değilse|-|-|-");
check("var, yok in the past, reported, conditional, question", () =>
  [["var", "past"], ["yok", "past"], ["var", "rep"], ["yok", "rep"], ["var", "cond"], ["yok", "cond"]].map(([v, t]) => M.copula(v, { tense: t, p: "o" }).text)
    .concat([M.copula("var", { tense: "pres", q: true, p: "o" }).text, M.copula("var", { tense: "past", q: true, p: "o" }).text, M.copula("var", { tense: "past", neg: true, p: "o" }).text]),
  ["vardı", "yoktu", "varmış", "yokmuş", "varsa", "yoksa", "var mı", "var mıydı", "yoktu"]);
para("assumption", "evde", "-|-|evdedir|-|-|evdelerdir");
para("assumption-negative", "evde", "-|-|evde değildir|-|-|-");
